/**
 * Resolve a root-relative public asset path for hosted subpath deployments.
 * @param {string | undefined | null} assetPath
 * @returns {string | undefined}
 */
export function publicAssetUrl(assetPath) {
  if (typeof assetPath !== 'string') return undefined;
  const trimmed = assetPath.trim();
  if (!trimmed) return undefined;
  if (/^https?:\/\//i.test(trimmed) || trimmed.startsWith('//') || trimmed.startsWith('data:')) {
    return trimmed;
  }
  if (typeof window === 'undefined') return trimmed;
  const base =
    typeof window.__SHELLUI_BASENAME__ === 'string' && window.__SHELLUI_BASENAME__.trim()
      ? window.__SHELLUI_BASENAME__.trim()
      : '';
  if (!base) return trimmed;
  if (trimmed.startsWith('/')) return `${base}${trimmed}`;
  return `${base}/${trimmed}`;
}
